#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;

    while (t--) {
        int n, k, d;
        cin >> n >> k >> d;

        vector<int> arr(n);
        for (int &x : arr) cin >> x;

        vector<int> freq(k + 1, 0);
        int distinct = 0;

        for (int i = 0; i < d; ++i) {
            if (freq[arr[i]]++ == 0) ++distinct;
        }

        int answer = distinct;

        for (int i = d; i < n; ++i) {
            if (--freq[arr[i - d]] == 0) --distinct;
            if (freq[arr[i]]++ == 0) ++distinct;
            answer = min(answer, distinct);
        }

        cout << answer << '\n';
    }

    return 0;
}

